});

test('invoiceTotals without discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0 },
      { qty: 1, unitPrice: 120000, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 9500 + 1 * 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals with single discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.total, 90000);
});

test('invoiceTotals with multiple discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 10 },
      { qty: 5, unitPrice: 20000, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000 + 100000);
  assert.equal(totals.discount, 10000 + 20000);
  assert.equal(totals.total, 170000);
});

test('invoiceTotals with 100 percent discount on all', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 100 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 47500);
  assert.equal(totals.total, 0);
});

test('invoiceTotals clamps negative total at zero', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 150 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  const expectedDiscount = Math.min(100000, Math.round(100000 * 150 / 100));
  assert(totals.total >= 0);
});

test('addLine with discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const result = addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 50 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 50);
});

test('addLine with DISCOUNT_INVALID', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
