test('invoiceTotals clamps negative total at zero', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 150 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  const expectedDiscount = Math.min(100000, Math.round(100000 * 150 / 100));
  assert(totals.total >= 0);
});

