test('invoiceTotals with gold tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const expectedSubtotal = 100 * 9500;
  const expectedDiscount = expectedSubtotal * 5 / 100;
